import type { Exercise } from './exercises';
import data from './fedb-exercises.json';
import descriptionsDe from './fedb-descriptions-de.json';

const DESCRIPTIONS_DE = descriptionsDe as Record<string, string>;

/**
 * Base catalog from free-exercise-db (Unlicense), generated by scripts/fedb-import.ts; German titles from scripts/fedb-names-de.json.
 * The short German guide of each entry is the dataset's English text, translated once (fedb-descriptions-de.json).
 */
export const FEDB_EXERCISES: Exercise[] = (data as Exercise[]).map((e) => {
  const description = DESCRIPTIONS_DE[e.id];
  return description ? { ...e, description } : e;
});

export { fedbImageFile } from './fedb-image';
